  /**
   * Notify that results are ready, that have been requested
   * using nsICMSMessage::asyncVerify[Detached]Signature()
   *
   * verificationResultCode matches synchronous result code from
   * nsICMSMessage::verify[Detached]Signature
   */
  void notify(in nsICMSMessage verifiedMessage,
              in nsresult verificationResultCode,
              in nsISMimeVerificationFailure reason);
};

/**
 * An interface to hold S/MIME signature verification reason
 * failures. The underlying values correspond to `mozilla::pkix::Result`
 * values indicating signature verification failure reasons.
 */
[scriptable, uuid(bc4a5aa7-2b1b-474f-82a3-00288f12070f)]
interface nsISMimeVerificationFailure : nsISupports {
  /** The `mozilla::pkix::Result` enumeration value. */
  readonly attribute int32_t enumValue;
  /** String representing the enum value. Of the form `Result::<ENUM_VALUE>`. */
  readonly attribute ACString enumString;
};
